<?php require_once __DIR__.'/functions.php';require_once __DIR__.'/app_init.php';require_login();$pdo=dogvive_db();$search=trim((string)($_GET['q']??''));$sql="SELECT u.id_usuario,u.Nombre,u.Apellido,u.Especialidad,u.Experiencia,u.Ciudad,u.Estado_verificacion,(SELECT COUNT(*) FROM certificacion c WHERE c.id_usuario=u.id_usuario AND c.Documento_archivo IS NOT NULL) AS tiene_cert FROM usuario u WHERE LOWER(u.Tipo_usuario)='entrenador'";$params=[];if($search!==''){$sql.=' AND (u.Nombre LIKE ? OR u.Apellido LIKE ? OR u.Especialidad LIKE ? OR u.Ciudad LIKE ?)';$like='%'.$search.'%';$params=[$like,$like,$like,$like];}$sql.=' ORDER BY u.Nombre';$q=$pdo->prepare($sql);$q->execute($params);$trainers=$q->fetchAll();start_app('Entrenadores','entrenadores');page_wrap_start('Encuentra el entrenador ideal','Consulta perfiles creados en Dog Vibe y sus especialidades.'); ?>
<div class="toolbar"><form method="get" style="display:flex;gap:10px;width:100%"><input name="q" value="<?= e($search) ?>" placeholder="Buscar por nombre, especialidad o ciudad..." style="flex:1"><button class="btn btn-primary" type="submit">Buscar</button><?php if($search!=='') echo btn('Limpiar',page_url('entrenadores'),'btn-secondary'); ?></form></div>
<?php if(!$trainers): ?><div class="card"><h3>No encontramos entrenadores</h3><p class="muted">Prueba otra búsqueda o vuelve más tarde. Los entrenadores aparecerán cuando creen su cuenta.</p></div><?php else: ?><div class="grid grid-3"><?php foreach($trainers as $t): ?><article class="card trainer-card"><div class="avatar" style="width:72px;height:72px;font-size:25px">🎓</div><div class="trainer-body"><span class="badge <?= ($t['Estado_verificacion']??'')==='Verificado'?'green':'' ?>"><?= e((string)($t['Estado_verificacion']??'Pendiente')) ?></span><h3><?= e(trim($t['Nombre'].' '.$t['Apellido'])) ?></h3><p class="muted">🎓 <?= e((string)($t['Especialidad']?:'Especialidad por definir')) ?></p><p class="muted">⏱ <?= (int)($t['Experiencia']??0) ?> años de experiencia</p><p class="muted">📍 <?= e((string)($t['Ciudad']??'Ciudad no indicada')) ?></p><p class="muted"><?= (int)$t['tiene_cert']>0?'Certificado adjunto para revisión':'Certificado pendiente de cargar' ?></p><div class="trainer-actions"><?= btn('Ver perfil',base_url().'/perfil-entrenador.php?id='.(int)$t['id_usuario'],'btn-secondary') ?><?= btn('Solicitar sesión',base_url().'/solicitud-servicio.php?entrenador='.(int)$t['id_usuario'],'btn-primary') ?></div></div></article><?php endforeach; ?></div><?php endif; ?><?php page_wrap_end();end_app();
